selector_to_html = {"a[href=\"#qpu\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">QPU \u6570\u5b57\u5b6a\u751f<a class=\"headerlink\" href=\"#qpu\" title=\"Link to this heading\">#</a></h1><p>\u6570\u5b57\u5b6a\u751f\u662f\u67d0\u4e2a QPU \u7684\u3001\u4ee5\u6807\u5b9a\u4e3a\u6761\u4ef6\u7684\u6a21\u578b\u3002\u5b83\u9884\u6d4b\u4f60\u5728\u786c\u4ef6\u4e0a\u4f1a\u770b\u5230\u7684\u6d4b\u91cf\u5206\u5e03\uff0c\u5e76\u628a\u8be5\u9884\u6d4b\u4e0e\u8bc1\u636e\u7ed1\u5b9a\uff1a\u9a8c\u8bc1\u8fc7\u54ea\u4e9b\u7535\u8def\u3001\u6d89\u53ca\u54ea\u4e9b\u7269\u7406\u8026\u5408\u3001\u591a\u6df1\u3001\u54ea\u6b21\u6807\u5b9a\u5feb\u7167\u3001\u7f6e\u4fe1\u754c\u662f\u591a\u5c11\u3002</p>", "a[href=\"#id6\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u524d\u77bb\u5f0f\u6bd4\u8f83\u5019\u9009\u6a21\u578b<a class=\"headerlink\" href=\"#id6\" title=\"Link to this heading\">#</a></h2><p>\u53ef\u4ee5\u5728\u5b8c\u5168\u76f8\u540c\u7684\u3001\u524d\u77bb\u6536\u96c6\u7684\u786c\u4ef6\u8ba1\u6570\u4e0a\u6bd4\u8f83\u73b0\u6709\u6a21\u578b\u4e0e\u5019\u9009\u6a21\u578b\u3002\u7ed3\u679c\u7ed9\u51fa\u4fdd\u5b88\u7684\u6709\u9650\u91c7\u6837\u533a\u95f4\uff0c\u5e76\u8fd4\u56de <code class=\"docutils literal notranslate\"><span class=\"pre\">improved</span></code>\u3001<code class=\"docutils literal notranslate\"><span class=\"pre\">degraded</span></code> \u6216 <code class=\"docutils literal notranslate\"><span class=\"pre\">inconclusive</span></code>\uff1b\u5b83\u7edd\u4e0d\u4f1a\u81ea\u52a8\u63d0\u5347\u6a21\u578b\uff0c\u6ca1\u6709\u660e\u786e\u7684\u5e94\u7528\u51b3\u7b56\u5c31\u4e0d\u4f1a\u6709\u6a21\u578b\u88ab\u63d0\u5347\u3002</p>", "a[href=\"#id4\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u4e0e\u786c\u4ef6\u505a\u9a8c\u8bc1<a class=\"headerlink\" href=\"#id4\" title=\"Link to this heading\">#</a></h2><p>\u9a8c\u8bc1\u6d41\u7a0b\u523b\u610f\u4fdd\u6301\u663e\u5f0f\u4e14\u53ef\u6062\u590d\uff1a</p>", "a[href=\"#id7\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u8fb9\u754c<a class=\"headerlink\" href=\"#id7\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#id3\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u6309\u62d3\u6251\u4e0e\u6df1\u5ea6\u9650\u5b9a\u8bc1\u636e<a class=\"headerlink\" href=\"#id3\" title=\"Link to this heading\">#</a></h2><p><code class=\"docutils literal notranslate\"><span class=\"pre\">TwinCircuitSupport</span></code> \u628a\u7edf\u8ba1\u5305\u7edc\u6536\u7a84\u5230\u771f\u6b63\u9a8c\u8bc1\u8fc7\u7684\u6709\u5411\u7269\u7406\u8026\u5408\u4e0e\u6700\u5927\u7535\u8def\u6df1\u5ea6\u3002\u5b83\u4e0d\u4f1a\u4ec5\u56e0\u4e3a\u5668\u4ef6\u4e0a\u5b58\u5728\u67d0\u4e2a\u8026\u5408\u5c31\u63a8\u65ad\u652f\u6301\uff0c\u5e76\u4e14\u5bf9\u672a\u6d4b\u8bd5\u7684\u76f8\u4e92\u4f5c\u7528\u3001\u53cd\u5411\u65b9\u5411\u3001\u8fc7\u5927\u6df1\u5ea6\u6216\u9636\u6570\u5927\u4e8e 2 \u7684\u64cd\u4f5c\u4e00\u5f8b\u5931\u8d25\u5373\u5173\u95ed\u3002</p><p>\u6765\u81ea\u540c\u4e00 QPU \u4e14\u65f6\u95f4\u76f8\u8fd1\u7684\u91cd\u53e0\u8bc1\u636e\u5355\u5143\u53ef\u4ee5\u7ec4\u5408\u6210\u8fde\u901a\u533a\u57df\u8986\u76d6\u62a5\u544a\uff0c\u7528\u4e8e\u7535\u8def\u6620\u5c04\u68c0\u67e5\uff0c\u540c\u65f6\u4fdd\u7559\u6709\u5411\u8fb9\u4e0e\u4fdd\u5b88\u4e0a\u4e0b\u9650\u3002\u5c40\u90e8\u7edf\u8ba1\u754c\u7edd\u4e0d\u4f1a\u88ab\u5408\u5e76\u6210\u533a\u57df\u7ea7\u7cbe\u5ea6\u7ed3\u8bba\u3002</p>", "a[href=\"#id2\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u9884\u6d4b\u662f\u4ec0\u4e48<a class=\"headerlink\" href=\"#id2\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#id1\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u4e3a\u4efb\u610f QPU \u6784\u5efa\u5b6a\u751f<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h2><p>\u4ece\u643a\u5e26\u5668\u4ef6\u753b\u50cf\u7684 <code class=\"docutils literal notranslate\"><span class=\"pre\">NoiseModel</span></code> \u51fa\u53d1\u3002\u6267\u884c\u76ee\u6807\u4e0e\u6709\u5e8f\u7269\u7406\u6620\u5c04\u4f1a\u6210\u4e3a\u5b6a\u751f\u4e0d\u53ef\u53d8\u8eab\u4efd\u7684\u4e00\u90e8\u5206\uff1a</p>", "a[href=\"#id5\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u8ddf\u8e2a\u968f\u65f6\u95f4\u6f02\u79fb<a class=\"headerlink\" href=\"#id5\" title=\"Link to this heading\">#</a></h2><p>\u5bf9\u540c\u4e00\u7ec4\u56fa\u5b9a\u7535\u8def\uff0c\u6807\u5b9a\u6f02\u79fb\u4e0e\u9884\u6d4b\u7cbe\u5ea6\u53ef\u4ee5\u5728\u6309\u65f6\u95f4\u6392\u5217\u7684\u5feb\u7167\u4e4b\u95f4\u5bf9\u9f50\uff0c\u4ece\u800c\u5f97\u5230\u53ef\u76f4\u63a5\u7ed8\u56fe\u7684\u5b6a\u751f\u2194QPU \u4e00\u81f4\u6027\u3001\u53c2\u8003\u4e00\u81f4\u6027\u3001\u53ef\u91cd\u590d\u6027\u4e0e\u5df2\u9a8c\u8bc1\u754c\u5e8f\u5217\uff0c\u4e14\u4e0d\u5ba3\u79f0\u56e0\u679c\u3001\u4e5f\u4e0d\u4ee3\u4e3a\u9009\u62e9\u6a21\u578b\u5347\u7ea7\u7b56\u7565\u3002\u5386\u53f2\u8bb0\u5f55\u4ee5\u79c1\u6709\u6743\u9650\u79bb\u7ebf\u6301\u4e45\u5316\uff0c\u5e76\u62d2\u7edd\u7834\u574f\u6027\u8986\u76d6\u3002</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
